import http.client
import json


conn = http.client.HTTPSConnection("192.168.0.1")
payload = json.dumps({
  "name": "string",
  "automations": [
    "string"
  ],
  "schedules": [
    {
      "start": "string",
      "end": "string"
    }
  ],
  "recordEverything": True,
  "activationDelay": 0
})
headers = {
  'Accept': 'application/json',
  'X-API-Key': '<X-API-Key>',
  'Content-Type': 'application/json'
}
conn.request("POST", "/proxy/protect/integration/v1/arm-profiles", payload, headers)
res = conn.getresponse()
data = res.read()
print(data.decode("utf-8"))

